728→        const segIdx = targetState.segments.findIndex(
729→          s => s.type === 'user_question' && s.questionData?.questionId === questionId
730→        );
731→        if (segIdx !== -1) {
732→          targetState.segments[segIdx] = {
733→            ...targetState.segments[segIdx],
734→            userAnswer: answers,
735→            userFreeText: freeText,
