747→
748→      // POST to backend
749→      try {
750→        await fetch('/api/chat/respond', {
751→          method: 'POST',
752→          headers: {
753→            'Content-Type': 'application/json',
754→            ...(userSessionId ? { 'X-Session-ID': userSessionId } : {}),
755→          },
756→          body: JSON.stringify({
757→            question_id: questionId,
758→            answers,
759→            free_text: freeText || null,
760→          }),
761→        });
762→      } catch (e) {
763→        console.error('Failed to respond to question:', e);
764→      }
765→    },
766→    [userSessionId]
767→  );
768→
769→  const loadMessages = useCallback((msgs: ChatMessage[], outgoingConversationId?: string | null, incomingConversationId?: string | null) => {
770→    const outgoing = outgoingConversationId || null;
771→    const incoming = incomingConversationId || null;
772→    activeConversationIdRef.current = incoming;
773→
774→    // Save outgoing conversation's messages to cache (only if not streaming --
775→    // streaming conversations keep their state in streamStatesRef)
776→    if (outgoing && !streamStatesRef.current.has(outgoing)) {
777→      const currentMsgs = messagesRef.current;
778→      if (currentMsgs.length > 0) {
779→        messagesCacheRef.current.set(outgoing, currentMsgs);
780→      }
781→    }
782→
783→    // Check if incoming conversation has an active stream (re-attachment)
784→    if (incoming) {
785→      const streamState = streamStatesRef.current.get(incoming);
786→      if (streamState) {
787→        // Re-attach: use live stream messages
788→        setMessages(streamState.messages);
789→        setIsStreaming(true);
790→        return;
791→      }
792→    }
793→
794→    // No active stream -- use backend data or cache
795→    let finalMsgs = msgs;
796→    if (incoming) {
797→      const cached = messagesCacheRef.current.get(incoming);
798→      if (cached && cached.length > 0 && cached.length > msgs.length) {
799→        finalMsgs = cached;
800→      }
801→      messagesCacheRef.current.delete(incoming);
802→    }
803→
804→    setMessages(finalMsgs);
805→    const hasStreamingMsg = finalMsgs.some(m => m.isStreaming);
806→    setIsStreaming(hasStreamingMsg);
807→    sessionIdRef.current = null;
808→    pendingHistoryRef.current = null;
809→  }, []);
810→
811→  const clearMessages = useCallback((outgoingConversationId?: string | null) => {
812→    const outgoing = outgoingConversationId || null;
813→    activeConversationIdRef.current = null;
814→
815→    // Save outgoing messages to cache if not streaming
816→    if (outgoing && !streamStatesRef.current.has(outgoing)) {
817→      const currentMsgs = messagesRef.current;
818→      if (currentMsgs.length > 0) {
819→        messagesCacheRef.current.set(outgoing, currentMsgs);
820→      }
821→    }
822→
823→    setMessages([]);
824→    setIsStreaming(false);
825→    sessionIdRef.current = null;
826→    pendingHistoryRef.current = null;
827→  }, []);
828→
829→  return (
830→    <AgentContext.Provider
831→      value={{ messages, isStreaming, sendMessage, editMessage, deleteMessage, clearMessages, loadMessages, respondToQuestion, streamingConversationIds }}
832→    >
833→      {children}
834→    </AgentContext.Provider>
835→  );
836→}
